package in.carenest.clinic.api;
import in.carenest.clinic.security.SecurityConfig.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.sql.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api") public class ClinicApi {
 private final JdbcTemplate db; private final JwtService jwt; public ClinicApi(JdbcTemplate db,JwtService jwt){this.db=db;this.jwt=jwt;}
 public record Login(@NotBlank String username,@NotBlank String password){} public record Session(String token,Map<String,Object> user){}
 @PostMapping("/auth/login") public Session login(@Valid @RequestBody Login x){var rows=db.query("select id,clinic_id,branch_id,display_name,role from users where username=? and active and password_hash=crypt(?,password_hash)",(r,n)->new TenantPrincipal(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(5),r.getString(4)),x.username(),x.password());if(rows.isEmpty())throw new ApiError(HttpStatus.UNAUTHORIZED,"Invalid username or password");var p=rows.getFirst();return new Session(jwt.issue(p),Map.of("id",p.userId(),"name",p.name(),"role",p.role(),"clinicId",Objects.toString(p.clinicId(),""),"branchId",Objects.toString(p.branchId(),"")));}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(required=false) LocalDate date){tenant(p);LocalDate d=date==null?db.queryForObject("select current_date",LocalDate.class):date;var counts=db.queryForMap("""
   select
     (select count(*) from appointments a where a.clinic_id=? and a.branch_id=? and a.status='BOOKED' and a.starts_at>=? and a.starts_at<?) appointments,
     (select coalesce(sum(a.price),0) from appointments a where a.clinic_id=? and a.branch_id=? and a.status in ('BOOKED','DONE') and a.starts_at>=? and a.starts_at<?) expected,
     (select count(*) from rooms r where r.clinic_id=? and r.branch_id=? and r.active) room_total,
     (select count(distinct a.room_id) from appointments a where a.clinic_id=? and a.branch_id=? and a.status='BOOKED' and a.starts_at<=current_timestamp and a.ends_at>current_timestamp) rooms_occupied,
     (select count(*) from practitioners pr where pr.clinic_id=? and pr.branch_id=? and pr.active) partners
   """,p.clinicId(),p.branchId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay(),p.clinicId(),p.branchId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay(),p.clinicId(),p.branchId(),p.clinicId(),p.branchId(),p.clinicId(),p.branchId());var upcoming=db.queryForList("select a.id,a.starts_at,c.full_name customer,s.name service,pr.full_name practitioner,r.name room,a.status from appointments a join customers c on c.id=a.customer_id join services s on s.id=a.service_id join practitioners pr on pr.id=a.practitioner_id join rooms r on r.id=a.room_id where a.clinic_id=? and a.branch_id=? and a.starts_at>=? and a.starts_at<? order by a.starts_at",p.clinicId(),p.branchId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay());var rooms=db.queryForList("""
   select r.id,r.name,r.room_type,
     case when exists(select 1 from appointments a where a.room_id=r.id and a.status='BOOKED' and a.starts_at<=current_timestamp and a.ends_at>current_timestamp) then 'OCCUPIED' else 'AVAILABLE' end status,
     (select min(a.ends_at) from appointments a where a.room_id=r.id and a.status='BOOKED' and a.starts_at<=current_timestamp and a.ends_at>current_timestamp) available_at
   from rooms r where r.clinic_id=? and r.branch_id=? and r.active order by r.room_type,r.name
   """,p.clinicId(),p.branchId());Map<String,Object> result=new LinkedHashMap<>();result.put("businessDate",d);result.put("summary",counts);result.put("appointments",upcoming);result.put("rooms",rooms);return result;}
 @GetMapping("/services") public List<Map<String,Object>> services(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return db.queryForList("select id,name,category,room_type,minutes,price,discount_percent,active from services where clinic_id=? order by name",p.clinicId());}
 @GetMapping("/me") public Map<String,Object> me(@AuthenticationPrincipal TenantPrincipal p){if(p==null)throw new ApiError(HttpStatus.UNAUTHORIZED,"Authentication required");Map<String,Object> out=new LinkedHashMap<>();out.put("id",p.userId());out.put("name",p.name());out.put("role",p.role());out.put("clinicId",p.clinicId());out.put("branchId",p.branchId());if(p.clinicId()!=null)out.putAll(db.queryForMap("select c.name clinic_name,c.logo_url,c.theme,c.default_slot_minutes,b.name branch_name,b.opens_at,b.closes_at from clinics c join branches b on b.id=? and b.clinic_id=c.id where c.id=?",p.branchId(),p.clinicId()));return out;}
 @GetMapping("/customers") public List<Map<String,Object>> customers(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="") String q){tenant(p);return db.queryForList("select c.id,c.full_name,c.phone,c.email,c.dob,c.address,c.guardian_name,c.guardian_phone,c.joined_on,c.free_cancellations_remaining,c.active,coalesce((select jsonb_agg(cs.service_id)::text from customer_services cs where cs.customer_id=c.id),'[]') service_ids,coalesce((select string_agg(s.name,', ') from customer_services cs join services s on s.id=cs.service_id where cs.customer_id=c.id),'') services from customers c where c.clinic_id=? and lower(c.full_name) like lower(?) order by c.full_name limit 100",p.clinicId(),"%"+q+"%");}
 public record Customer(@NotBlank String fullName,@NotBlank String phone,String email,LocalDate dob,String address,String guardianName,String guardianPhone,List<UUID> serviceIds){}
 @PostMapping("/customers") @Transactional @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addCustomer(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody Customer x){tenant(p);UUID id=UUID.randomUUID();db.update("insert into customers(id,clinic_id,branch_id,full_name,phone,email,dob,address,guardian_name,guardian_phone,free_cancellations_remaining) select ?,?,?,?,?,?,?,?,?,?,free_customer_cancellations from clinics where id=?",id,p.clinicId(),p.branchId(),x.fullName(),x.phone(),x.email(),x.dob(),x.address(),x.guardianName(),x.guardianPhone(),p.clinicId());if(x.serviceIds()!=null)for(UUID service:x.serviceIds()){int n=db.update("insert into customer_services(customer_id,service_id) select ?,id from services where id=? and clinic_id=?",id,service,p.clinicId());if(n==0)throw new ApiError(HttpStatus.BAD_REQUEST,"Invalid customer service");}return Map.of("id",id);}
 public record Booking(@NotNull UUID customerId,@NotNull UUID practitionerId,@NotNull UUID serviceId,@NotNull LocalDateTime startsAt){}
 @PostMapping("/appointments") @Transactional public Map<String,Object> book(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody Booking x){tenant(p);db.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Long.class,p.branchId()+"|"+x.startsAt());var service=db.queryForMap("select room_type,minutes,price from services where id=? and clinic_id=? and active",x.serviceId(),p.clinicId());int mins=(Integer)service.get("minutes");LocalDateTime end=x.startsAt().plusMinutes(mins);Integer partnerBusy=db.queryForObject("select count(*) from appointments where clinic_id=? and practitioner_id=? and status='BOOKED' and starts_at<? and ends_at>?",Integer.class,p.clinicId(),x.practitionerId(),end,x.startsAt());if(partnerBusy!=null&&partnerBusy>0)throw new ApiError(HttpStatus.CONFLICT,"Practitioner is not available for this slot");var rooms=db.queryForList("select r.id from rooms r where r.clinic_id=? and r.branch_id=? and r.room_type=? and r.active and not exists(select 1 from appointments a where a.room_id=r.id and a.status='BOOKED' and a.starts_at<? and a.ends_at>?) order by r.name limit 1",UUID.class,p.clinicId(),p.branchId(),service.get("room_type"),end,x.startsAt());if(rooms.isEmpty())throw new ApiError(HttpStatus.CONFLICT,"No suitable room is available for this slot");UUID id=UUID.randomUUID();db.update("insert into appointments(id,clinic_id,branch_id,customer_id,practitioner_id,service_id,room_id,starts_at,ends_at,price,booked_by) values(?,?,?,?,?,?,?,?,?,?,?)",id,p.clinicId(),p.branchId(),x.customerId(),x.practitionerId(),x.serviceId(),rooms.getFirst(),x.startsAt(),end,service.get("price"),p.userId());db.update("insert into booking_events(clinic_id,appointment_id,event_type,actor_user_id,new_values) values(?,?,'BOOKED',?,jsonb_build_object('startsAt',?::text))",p.clinicId(),id,p.userId(),x.startsAt().toString());return Map.of("id",id,"roomId",rooms.getFirst(),"endsAt",end,"status","BOOKED");}
 public record Cancel(String reason,@NotNull String cancelledBy){}
 @PostMapping("/appointments/{id}/cancel") @Transactional public Map<String,Object> cancel(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@RequestBody Cancel x){tenant(p);var a=db.queryForMap("select starts_at,price,customer_id,status from appointments where id=? and clinic_id=? for update",id,p.clinicId());if(!"BOOKED".equals(a.get("status")))throw new ApiError(HttpStatus.CONFLICT,"Only booked appointments can be cancelled");boolean practitioner="PRACTITIONER".equalsIgnoreCase(x.cancelledBy());long notice=Duration.between(LocalDateTime.now(),((Timestamp)a.get("starts_at")).toLocalDateTime()).toHours();int free=db.queryForObject("select free_customer_cancellations_remaining from customers where id=?",Integer.class,a.get("customer_id"));int required=db.queryForObject("select cancellation_notice_hours from clinics where id=?",Integer.class,p.clinicId());BigDecimal charge=BigDecimal.ZERO;if(!practitioner&&notice<required){if(free>0)db.update("update customers set free_cancellations_remaining=free_cancellations_remaining-1 where id=?",a.get("customer_id"));else charge=(BigDecimal)a.get("price");}if(practitioner)db.update("update customers set free_cancellations_remaining=free_cancellations_remaining+(select practitioner_cancel_credit from clinics where id=?) where id=?",p.clinicId(),a.get("customer_id"));db.update("update appointments set status='CANCELLED',version=version+1 where id=?",id);db.update("insert into booking_events(clinic_id,appointment_id,event_type,actor_user_id,charge,new_values) values(?,?,'CANCELLED',?,?,jsonb_build_object('reason',?))",p.clinicId(),id,p.userId(),charge,x.reason());return Map.of("status","CANCELLED","charge",charge);}
 public record ConfirmPayment(@NotNull UUID customerId,@DecimalMin("0.01") BigDecimal amount,BigDecimal adjustment,String notes,@NotBlank String otp,@NotBlank String method){}
 @PostMapping("/payments/confirm") @Transactional public Map<String,Object> pay(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ConfirmPayment x){tenant(p);Boolean ok=db.queryForObject("select payment_otp_hash=crypt(?,payment_otp_hash) from clinics where id=?",Boolean.class,x.otp(),p.clinicId());if(!Boolean.TRUE.equals(ok))throw new ApiError(HttpStatus.UNAUTHORIZED,"Invalid payment confirmation OTP");UUID id=UUID.randomUUID();String receipt="RCPT-"+LocalDate.now().getYear()+"-"+id.toString().substring(0,8).toUpperCase();String receiptUrl="/api/public/receipts/"+id+"/pdf";db.update("insert into payments(id,clinic_id,branch_id,customer_id,amount,adjustment,notes,status,method,receipt_number,receipt_url,confirmed_at,confirmed_by) values(?,?,?,?,?,?,?,'CONFIRMED',?,?,?,now(),?)",id,p.clinicId(),p.branchId(),x.customerId(),x.amount(),x.adjustment()==null?BigDecimal.ZERO:x.adjustment(),x.notes(),x.method(),receipt,receiptUrl,p.userId());var customer=db.queryForMap("select phone,full_name from customers where id=? and clinic_id=?",x.customerId(),p.clinicId());db.update("insert into whatsapp_outbox(clinic_id,recipient,template_type,payload) values(?,?,'PAYMENT_RECEIPT',jsonb_build_object('customer',?,'receiptNumber',?,'receiptUrl',?))",p.clinicId(),customer.get("phone"),customer.get("full_name"),receipt,receiptUrl);return Map.of("id",id,"receiptNumber",receipt,"receiptUrl",receiptUrl,"whatsappStatus","QUEUED");}
 public record ClinicOnboarding(@NotBlank String clinicName,@NotBlank String slug,@NotBlank String branchName,@NotBlank String address,@NotBlank String ownerName,@Email String ownerUsername,@Size(min=12) String ownerPassword,@NotBlank String ownerPhone,String whatsappPhone,String email,LocalTime opensAt,LocalTime closesAt,Integer slotMinutes){}
 @GetMapping("/admin/clinics") public List<Map<String,Object>> findClinics(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="") String q){if(p==null||!"PLATFORM_ADMIN".equals(p.role()))throw new ApiError(HttpStatus.FORBIDDEN,"Platform administrator required");String term="%"+q.trim()+"%";return db.queryForList("""
   select c.id,c.name,c.slug,c.active,c.email,c.whatsapp_phone,c.created_at,
          count(distinct b.id) branches,count(distinct u.id) users
   from clinics c left join branches b on b.clinic_id=c.id left join users u on u.clinic_id=c.id
   where lower(c.name) like lower(?) or lower(c.slug) like lower(?) or lower(coalesce(c.email,'')) like lower(?)
   group by c.id order by c.created_at desc limit 100
   """,term,term,term);}
 @PostMapping("/admin/clinics") @Transactional public Map<String,Object> onboardClinic(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ClinicOnboarding x){if(p==null||!"PLATFORM_ADMIN".equals(p.role()))throw new ApiError(HttpStatus.FORBIDDEN,"Platform administrator required");UUID clinic=UUID.randomUUID(),branch=UUID.randomUUID(),owner=UUID.randomUUID();Integer exists=db.queryForObject("select count(*) from clinics where slug=?",Integer.class,x.slug());if(exists!=null&&exists>0)throw new ApiError(HttpStatus.CONFLICT,"Clinic slug already exists");db.update("insert into clinics(id,name,slug,owner_phone,whatsapp_phone,email,default_slot_minutes,payment_otp_hash) values(?,?,?,?,?,?,?,crypt('987600',gen_salt('bf')))",clinic,x.clinicName(),x.slug(),x.ownerPhone(),x.whatsappPhone(),x.email(),x.slotMinutes()==null?45:x.slotMinutes());db.update("insert into branches(id,clinic_id,name,address,opens_at,closes_at) values(?,?,?,?,?,?)",branch,clinic,x.branchName(),x.address(),x.opensAt()==null?LocalTime.of(9,30):x.opensAt(),x.closesAt()==null?LocalTime.of(20,0):x.closesAt());db.update("insert into users(id,clinic_id,branch_id,username,password_hash,display_name,role,phone,joined_on) values(?,?,?,?,crypt(?,gen_salt('bf')),?,'OWNER',?,current_date)",owner,clinic,branch,x.ownerUsername(),x.ownerPassword(),x.ownerName(),x.ownerPhone());return Map.of("clinicId",clinic,"branchId",branch,"ownerUserId",owner);}
 public record StaffOnboarding(@Email String username,@Size(min=12) String password,@NotBlank String displayName,@NotBlank String role,String phone,LocalDate joinedOn,String engagement,BigDecimal yearsExperience){}
 @PostMapping("/staff") @Transactional public Map<String,Object> onboardStaff(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody StaffOnboarding x){tenant(p);if(!List.of("OWNER","PLATFORM_ADMIN").contains(p.role()))throw new ApiError(HttpStatus.FORBIDDEN,"Clinic owner required");if(!List.of("RECEPTIONIST","PRACTITIONER").contains(x.role()))throw new ApiError(HttpStatus.BAD_REQUEST,"Role must be RECEPTIONIST or PRACTITIONER");UUID user=UUID.randomUUID();db.update("insert into users(id,clinic_id,branch_id,username,password_hash,display_name,role,phone,joined_on) values(?,?,?,?,crypt(?,gen_salt('bf')),?,?,?,?)",user,p.clinicId(),p.branchId(),x.username(),x.password(),x.displayName(),x.role(),x.phone(),x.joinedOn()==null?LocalDate.now():x.joinedOn());Map<String,Object> out=new LinkedHashMap<>();out.put("userId",user);if("PRACTITIONER".equals(x.role())){UUID practitioner=UUID.randomUUID();db.update("insert into practitioners(id,clinic_id,user_id,branch_id,full_name,joined_on,engagement,years_experience) values(?,?,?,?,?,?,?,?)",practitioner,p.clinicId(),user,p.branchId(),x.displayName(),x.joinedOn()==null?LocalDate.now():x.joinedOn(),x.engagement()==null?"FULL_TIME":x.engagement(),x.yearsExperience()==null?BigDecimal.ZERO:x.yearsExperience());out.put("practitionerId",practitioner);}return out;}
 public record PasswordReset(@NotBlank String username,@Size(min=12,max=128) String newPassword){}
 @PutMapping("/admin/users/password") @Transactional public Map<String,Object> resetUserPassword(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody PasswordReset x){if(p==null||!"PLATFORM_ADMIN".equals(p.role()))throw new ApiError(HttpStatus.FORBIDDEN,"Platform administrator required");int updated=db.update("update users set password_hash=crypt(?,gen_salt('bf')) where lower(username)=lower(?) and role<>'PLATFORM_ADMIN'",x.newPassword(),x.username());if(updated==0)throw new ApiError(HttpStatus.NOT_FOUND,"Clinic user was not found");return Map.of("username",x.username(),"status","PASSWORD_UPDATED");}
 private void tenant(TenantPrincipal p){if(p==null||p.clinicId()==null)throw new ApiError(HttpStatus.FORBIDDEN,"A clinic context is required");}
 @ResponseStatus class ApiError extends RuntimeException{final HttpStatus status;ApiError(HttpStatus s,String m){super(m);status=s;}}
 @ExceptionHandler(ApiError.class) ResponseEntity<?> error(ApiError e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
}
